import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { patronsKey, usePatrons, usePeople, type Person } from '../people/usePeople';
import { useClaims } from '../claims/useClaims';
import { sumDues } from '../rates/useRates';
import { useSheetToday } from '../today/useSheetToday';

/** The first day (yyyy-mm-dd) of the 90 days up to and including a day. */
function windowStart(today: string): string {
  return new Date(Date.parse(`${today}T00:00:00Z`) - 89 * 86_400_000).toISOString().slice(0, 10);
}

/** A person's patrons: the other people on the sheet they have named (names sorted, comma and space
 *  separated), their backing (the due frozen when each of their patrons' SETTLED claims dated within the 90 days up
 *  to and including the sheet's today was settled, added up; 0.00 with none),
 *  and a picker that names one more. Naming themselves, or a patron twice, is refused. */
function PersonPatrons({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const patrons = usePatrons(sheetId);
  const claims = useClaims(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const queryClient = useQueryClient();
  const [chosen, setChosen] = useState('');

  const named = (patrons.data ?? [])
    .filter((x) => x.personId === personId)
    .map((x) => people.data?.find((p) => p.id === x.patronId))
    .filter((p): p is Person => p !== undefined);
  const names = named.map((p) => p.name).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const from = today === undefined ? undefined : windowStart(today);
  const patronIds = new Set(named.map((p) => p.id));
  const backing = sumDues((claims.data ?? [])
    .filter((c) => patronIds.has(c.personId) && c.status === 'SETTLED' && c.due !== null
      && from !== undefined && today !== undefined && c.date >= from && c.date <= today)
    .map((c) => c.due as string));

  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/patrons`, { patronId }),
    onSuccess: async () => {
      setChosen('');
      await queryClient.invalidateQueries({ queryKey: patronsKey(sheetId) });
    },
  });

  return (
    <>
      <td data-testid="person-patrons">{names.join(', ')}</td>
      <td data-testid="person-backing">{backing}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={chosen}
          onChange={(e) => {
            setChosen(e.target.value);
            add.reset();
          }}
        >
          <option value="">Patron…</option>
          {(people.data ?? []).map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending}
          onClick={() => {
            add.reset();
            add.mutate(Number(chosen));
          }}
        >
          Add patron
        </button>
        {add.isError && <span data-testid="person-patron-error">{add.error.message}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHead.fill({
    order: 50,
    Component: () => (
      <>
        <th>Patrons</th>
        <th>Backing</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 50, Component: PersonPatrons }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { peopleKey, usePeople, type Person } from '../people/usePeople';
import { usePersonRowAction } from '../people/usePersonRowAction';
import { useShowRetired } from './useShowRetired';

/** A person's retirement: whether they are retired and from when, and a date (blank: the sheet's
 *  today) and button that retire them. A person with a date set counts as retired at once; no claim
 *  of theirs may be dated after it, and the list leaves them out unless "show retired" is on. */
function PersonRetire({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const p = people.data?.find((x) => x.id === personId);
  const [date, setDate] = useState('');

  const retire = useMutation({
    mutationFn: (raw: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/retire`, { date: raw.trim() }),
    onSuccess: async () => {
      setDate('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });
  const announce = usePersonRowAction(sheetId, personId, retire.reset);

  return (
    <>
      <td data-testid="person-retired">{p?.retiredFrom ? 'yes' : 'no'}</td>
      <td data-testid="person-retired-from">{p?.retiredFrom ?? ''}</td>
      <td>
        <input
          type="text"
          placeholder="yyyy-mm-dd"
          data-testid="person-retire-date"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            retire.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-retire"
          disabled={retire.isPending}
          onClick={() => {
            announce();
            retire.reset();
            retire.mutate(date);
          }}
        >
          Retire
        </button>
        {retire.isError && <span data-testid="person-error">{retire.error.message}</span>}
      </td>
    </>
  );
}

/** The "show retired" toggle: off when the screen is first opened. */
function ShowRetired() {
  const [on, setOn] = useShowRetired();
  return (
    <label>
      <input type="checkbox" data-testid="show-retired" checked={on} onChange={(e) => setOn(e.target.checked)} /> Show
      retired
    </label>
  );
}

export const contributions = [
  SheetBody.fill({ order: 5, Component: () => <ShowRetired /> }),
  PersonColumnHead.fill({
    order: 40,
    Component: () => (
      <>
        <th>Retired</th>
        <th>Retired from</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 40, Component: PersonRetire }),
];
import { useEffect, useId } from 'react';

// The actions on a person's row (statement, hold, retire) live in separate slots, but share the row's one
// `person-error`. Taking any of them announces it on the row, and every other action there clears its old
// error, so a refusal left by one action never shows beside (or for) the next.
const bus = new EventTarget();

/** Clear this action's error (`reset`) when another action on the same row is taken; returns the
 *  `announce` to call as this action is taken. */
export function usePersonRowAction(sheetId: string, personId: number, reset: () => void): () => void {
  const self = useId();
  const row = `${sheetId}/${personId}`;
  useEffect(() => {
    const listener = (e: Event) => {
      const d = (e as CustomEvent<{ row: string; from: string }>).detail;
      if (d.row === row && d.from !== self) reset();
    };
    bus.addEventListener('person-action', listener);
    return () => bus.removeEventListener('person-action', listener);
  }, [row, self, reset]);
  return () => bus.dispatchEvent(new CustomEvent('person-action', { detail: { row, from: self } }));
}
